def fizzbuzz(n: int) -> list[str]:
    """Return the FizzBuzz sequence for integers 1 through n."""

    if n < 1:
        return []

    result = [str(i) for i in range(1, n + 1)]

    for index, value in enumerate(result):
        number = index + 1
        if number % 3 == 0 and number % 5 == 0:
            result[index] = "FizzBuzz"
        elif number % 3 == 0:
            result[index] = "Fizz"
        elif number % 5 == 0:
            result[index] = "Buzz"

    return result


if __name__ == "__main__":
    print(fizzbuzz(15))
