def flatten(d: dict) -> dict:
    """Flatten one level of nested dicts, joining keys with a dot."""
    result = {}

    for key, value in d.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                result[f"{key}.{sub_key}"] = sub_value
        else:
            result[key] = value

    return result


# Example usage:
print(flatten({"a": {"b": 1}}))          # {'a.b': 1}
print(flatten({"c": 2}))                 # {'c': 2}
```

