def parse_row(line: str) -> list[str]:
    fields = []
    current = ""
    in_quotes = False

    for char in line:
        if in_quotes:
            if char == '"':
                # Check for a doubled quote (escaped quote inside the field).
                if len(current) > 0 and current[-1] == '"':
                    current += '"'
                else:
                    in_quotes = False
            elif char == ',':
                fields.append(current)
                current = ""
            else:
                current += char
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(current)
                current = ""
            else:
                current += char

    fields.append(current)
    return fields
