import re


def parse_money(s: str) -> float | None:
    if not isinstance(s, str):
        return None

    cleaned = s.replace(",", "").replace("$", "")
    try:
        value = float(cleaned)
    except ValueError:
        return None

    # Reject non-finite results and empty strings.
    if not cleaned or not re.fullmatch(r"\d+(\.\d+)?", cleaned):
        return None

    return value


if __name__ == "__main__":
    print(parse_money("$1,234.50"))  # 1234.5
    print(parse_money("1234.5"))     # 1234.5
    print(parse_money(""))           # None
    print(parse_money("n/a"))        # None
```

